/** What each art kind has to be, for the "qué arte necesita" line under every slot. */
export const ART_KIND_NOTES = {
  projectile: { label: 'Proyectil', needs: 'animación Move (y opcional Impact). Vuela y choca.', kinds: ['projectile', 'fx'] },
  fx: { label: 'Efecto', needs: 'una animación (la primera) de un solo uso.', kinds: ['fx', 'projectile'] },
  warning: { label: 'Aviso', needs: 'una animación en bucle; se estira al tamaño del aviso.', kinds: ['fx', 'projectile'] },
  prop: { label: 'Objeto', needs: 'una animación (Move si hay); se dibuja en la mano del jefe.', kinds: ['projectile', 'fx', 'enemy'] },
};

export function attackLabel(type, catalogEntry) {
  return ATTACK_NOTES[type]?.label || catalogEntry?.label || type;
}
